export const lessonsData: Lesson[] = [
  { id: "what-is-stock-market", slug: "what-is-stock-market", title: "What is the Stock Market", icon: "📈", category: "Beginner", difficulty: "Easy", duration_minutes: 6, xp_reward: 20, summary: "Understand what the stock market actually is, how it works, and why it exists.", why_it_matters: "Every asset you trade passes through some form of market. Understanding the mechanics gives you a structural edge.", content: [{ heading: "The basics", body: ["The stock market is a network where buyers and sellers trade shares of publicly listed companies.", "Prices move based on supply and demand."] }, { heading: "How it actually works", body: ["Modern stock markets are electronic. Orders are routed to exchanges like NYSE or NASDAQ.", "Market makers provide liquidity by always being willing to buy or sell, profiting from the spread."] }, { heading: "Why it matters for you", body: ["The stock market is the primary mechanism for building long-term wealth. But it's also where fortunes are lost when people treat it like a casino.", "Understanding structure helps you make better decisions."] }, { heading: "When this fails", body: ["Markets can behave irrationally for extended periods. Understanding mechanics doesn't guarantee logical price movements."] }], common_mistake: "Treating the stock market like gambling — buying based on tips without understanding you're buying ownership in a real business.", practical_example: "Apple releases a new iPhone, buyers flood in pushing the stock up. But if sales disappoint, sellers take over and price drops.", takeaways: ["The stock market is a supply-and-demand auction", "Prices move from collective buying/selling pressure", "Market makers provide liquidity via the bid-ask spread", "Understanding structure gives you an edge"], quiz: [{ question: "What fundamentally drives stock prices?", options: ["Company revenue", "Supply and demand", "Government regulation", "Broker fees"], correctAnswer: 1, explanation: "The immediate driver of price is the balance of supply and demand.", tags: ["Beginner"] }, { question: "What do market makers do?", options: ["Set prices for government", "Provide liquidity by buying and selling", "Block retail traders", "Prevent stocks from falling"], correctAnswer: 1, explanation: "Market makers provide liquidity by quoting both buy and sell prices.", tags: ["Beginner"] }, { question: "When you buy a share, what do you own?", options: ["A loan to the company", "Future dividends", "Partial ownership in a business", "A bet on price"], correctAnswer: 2, explanation: "A share represents fractional ownership in the company.", tags: ["Beginner"] }], related_lessons: ["crypto-vs-stocks-forex", "market-sessions"], illustrations: [{ type: "bull-bear-cycle", caption: "Markets move in cycles — understanding where we are helps you adapt strategy", afterSection: 2 }] },
  { id: "crypto-vs-stocks-forex", slug: "crypto-vs-stocks-forex", title: "Crypto vs Stocks vs Forex", icon: "🔄", category: "Beginner", difficulty: "Easy", duration_minutes: 7, xp_reward: 20, summary: "Compare the three most popular asset classes.", why_it_matters: "Each market has different rules, hours, volatility, and risk. Trading crypto like stocks will cost you.", content: [{ heading: "Stocks", body: ["Trade during set hours (9:30 AM–4 PM EST). Represent real company ownership.", "Regulated, less volatile than crypto, driven by earnings and macro."] }, { heading: "Cryptocurrency", body: ["24/7 markets, highly volatile. A 10% daily move is normal.", "Fewer regulations, more scams, sentiment-driven."] }, { heading: "Forex", body: ["The largest market. Trade currency pairs nearly 24 hours on weekdays.", "Highly liquid, smaller moves, often uses significant leverage."] }, { heading: "Choosing your focus", body: ["No 'best' market. Specialise in one before spreading thin."] }], common_mistake: "Applying the same strategy across all markets without adapting to different volatility and drivers.", practical_example: "AAPL moves 2-3% on earnings. Bitcoin drops 8% from a tweet. EUR/USD moves 0.5%. Same skill, very different volatility.", takeaways: ["Stocks: set hours. Crypto: 24/7. Forex: near 24h weekdays", "Crypto is most volatile; forex has smallest daily moves", "Each market has different drivers", "Specialise before diversifying"], quiz: [{ question: "Which market operates 24/7?", options: ["Stocks", "Forex", "Cryptocurrency", "All"], correctAnswer: 2, explanation: "Crypto never closes.", tags: ["Beginner"] }, { question: "Which has the smallest daily moves?", options: ["Crypto", "Stocks", "Forex", "All equal"], correctAnswer: 2, explanation: "Forex pairs typically move less than 1% per day.", tags: ["Beginner"] }, { question: "Why not use one strategy for all markets?", options: ["Brokers won't allow it", "Different volatility, hours, and drivers", "Need different accounts", "Strategies always work everywhere"], correctAnswer: 1, explanation: "Each market has fundamentally different characteristics.", tags: ["Beginner"] }], related_lessons: ["what-is-stock-market", "market-sessions"] },
  { id: "market-sessions", slug: "market-sessions", title: "Market Sessions & Timing", icon: "🕐", category: "Beginner", difficulty: "Easy", duration_minutes: 5, xp_reward: 20, summary: "Learn about global trading sessions and how timing affects price action.", why_it_matters: "Trading during the wrong session means low liquidity, wide spreads, and false signals.", content: [{ heading: "Three major sessions", body: ["Asia (Tokyo), Europe (London), North America (New York).", "Asia is quieter. London spikes volume. New York is most active for US stocks."] }, { heading: "Session overlaps", body: ["London-New York overlap (8 AM–12 PM EST) is the most active period globally.", "Asia-London overlap is significant for JPY and EUR pairs."] }, { heading: "Impact on your strategy", body: ["Scalping needs active sessions. Low-volume hours produce choppy, unpredictable action."] }], common_mistake: "Trading low-liquidity hours and wondering why signals fail and spreads eat profits.", practical_example: "A GBP/USD breakout at 3 AM EST fakes out in quiet Asia session. The same setup at 9 AM during London-NY overlap has real follow-through.", takeaways: ["Three sessions: Asia, London, New York", "London-NY overlap has deepest liquidity", "Low-liquidity sessions produce false signals", "Match your schedule to the right session"], quiz: [{ question: "Which overlap is most active?", options: ["Asia-London", "London-New York", "NY-Asia", "All equal"], correctAnswer: 1, explanation: "London-NY combines the two largest financial centres.", tags: ["Beginner"] }, { question: "What happens in low-liquidity hours?", options: ["Better prices", "Wider spreads and chop", "More predictable trends", "Higher profits"], correctAnswer: 1, explanation: "Fewer participants means wider spreads and erratic movements.", tags: ["Beginner"] }, { question: "Which session has smallest moves?", options: ["New York", "London", "Asia", "Identical"], correctAnswer: 2, explanation: "Asia generally sees lower volume and smaller ranges.", tags: ["Beginner"] }], related_lessons: ["what-is-stock-market", "crypto-vs-stocks-forex"], illustrations: [{ type: "session-timeline", caption: "Global trading sessions and their overlaps throughout the day", afterSection: 1 }] },
  { id: "bull-bear-markets", slug: "bull-bear-markets", title: "Bull vs Bear Markets", icon: "🐂", category: "Beginner", difficulty: "Easy", duration_minutes: 5, xp_reward: 20, summary: "Understand market cycles and how to adapt your approach.", why_it_matters: "Trading bearish markets with bullish strategies is swimming against the current.", content: [{ heading: "Definitions", body: ["Bull = 20%+ rise from a low. Bear = 20%+ decline from a high.", "These reflect shifts in sentiment and risk appetite."] }, { heading: "Identifying the trend", body: ["Higher highs and higher lows = uptrend. Lower highs and lower lows = downtrend.", "Price above the 200-day MA = generally bullish."] }, { heading: "Adapting strategy", body: ["Bull: buying dips and breakouts work. Bear: rallies fail, cash is king.", "Worst trades come from fighting the trend."] }], common_mistake: "Buying every dip in a bear market. Bear markets can last months or years.", practical_example: "2022 crypto winter: Bitcoin from $69k to $15k. Buying dips at $50k, $40k, $30k = massive losses.", takeaways: ["Bull = sustained rising; Bear = sustained falling", "HH + HL confirm uptrends", "Adapt strategy to market regime", "Fighting the trend is expensive"], quiz: [{ question: "What defines a bear market?", options: ["5% daily drop", "20%+ decline from a high", "Low volume", "All-time low"], correctAnswer: 1, explanation: "Bear = 20%+ decline from peak.", tags: ["Beginner"] }, { question: "What confirms an uptrend?", options: ["LH + LL", "HH + HL", "Flat + volume", "Random movement"], correctAnswer: 1, explanation: "Each peak higher and each dip higher than the last.", tags: ["Beginner"] }, { question: "Risk of buying every dip in a bear market?", options: ["Fees add up", "Each bounce may be a trap", "Run out of watchlist space", "Dips don't exist"], correctAnswer: 1, explanation: "Dead-cat bounces trap buyers before the next leg down.", tags: ["Beginner"] }], related_lessons: ["support-resistance", "trend-market-structure"], illustrations: [{ type: "bull-bear-cycle", caption: "Market cycles: Accumulation → Bull → Distribution → Bear", afterSection: 0 }, { type: "trend-structure", caption: "Higher highs/lows define uptrends; lower highs/lows define downtrends", afterSection: 1 }] },
  { id: "support-resistance", slug: "support-resistance", title: "Support & Resistance", icon: "📊", category: "Technical", difficulty: "Medium", duration_minutes: 8, xp_reward: 30, summary: "Identify price levels where buying or selling pressure clusters.", why_it_matters: "S&R is the foundation of technical analysis. Every strategy relies on these levels.", content: [{ heading: "What are S&R?", body: ["Support = buying pressure zone. Resistance = selling pressure zone.", "They form because traders remember previous price points — a self-fulfilling prophecy."] }, { heading: "Zones, not lines", body: ["S&R are zones, not exact lines. Price rarely reverses at a pixel-perfect level.", "Drawing them too precisely leads to premature entries/exits."] }, { heading: "How to use them", body: ["Buy near support with tight stops below. Sell near resistance.", "Broken resistance often becomes support (role reversal). More tests = more significant but closer to breaking."] }, { heading: "When this fails", body: ["In strong trends, S&R levels get steamrolled."] }], common_mistake: "Drawing exact lines and getting stopped out when price wicks through before reversing. Use zones.", practical_example: "Tesla bounced off $180 three times. Buy at $182, stop at $175. Price dips to $179, reverses to $210. The zone held.", takeaways: ["Support = buying zone; Resistance = selling zone", "Think in zones, not lines", "Broken resistance becomes support", "More tests = significant but fragile"], quiz: [{ question: "Why think of S&R as zones?", options: ["Looks better", "Price rarely reverses at exact levels", "Brokers require it", "Lines aren't on mobile"], correctAnswer: 1, explanation: "Price action is messy — zones account for natural variation.", tags: ["Technical"] }, { question: "What is role reversal?", options: ["Market opens opposite", "Broken resistance becomes support", "Bulls become bears", "Ticker change"], correctAnswer: 1, explanation: "Broken levels often reverse their role — resistance becomes support.", tags: ["Technical"] }, { question: "What happens when support is tested many times?", options: ["Unbreakable", "More significant but more likely to break", "Stops being relevant", "Delisted"], correctAnswer: 1, explanation: "Each test depletes the buyer pool, making an eventual break more likely.", tags: ["Technical"] }, { question: "S&R in strong trends?", options: ["More reliable", "Get broken easily", "Disappear", "Double in width"], correctAnswer: 1, explanation: "Strong trends overwhelm levels that would normally hold.", tags: ["Technical"] }], related_lessons: ["trend-market-structure", "understanding-rsi"] },
  { id: "understanding-rsi", slug: "understanding-rsi", title: "Understanding RSI", icon: "📉", category: "Technical", difficulty: "Medium", duration_minutes: 7, xp_reward: 30, summary: "Learn what RSI measures, how to read it, and when it lies.", why_it_matters: "RSI is widely used but widely misused. Learning what it actually tells you prevents false signals.", content: [{ heading: "What RSI measures", body: ["RSI measures speed and magnitude of recent price changes (0–100).", "Above 70 = 'overbought', below 30 = 'oversold'. But these labels mislead beginners."] }, { heading: "The overbought/oversold trap", body: ["RSI 70+ does NOT mean sell. In strong uptrends, RSI stays above 70 for weeks.", "RSI below 30 in a bear market doesn't mean buy the dip."] }, { heading: "How to use RSI", body: ["Use divergences: price makes a new high but RSI makes a lower high = fading momentum.", "Use context: in an uptrend, RSI at 40-50 = buying opportunity."] }, { heading: "When this fails", body: ["RSI divergences can persist before reversing. It's a confirmation tool, not standalone."] }], common_mistake: "Automatically selling at RSI 70 or buying at 30. This means selling strong trends early and buying falling knives.", practical_example: "NVIDIA's RSI stayed above 70 for three weeks during its AI rally. Selling at 70 missed a 40% move.", takeaways: ["RSI measures momentum, not buy/sell signals", "Overbought ≠ sell; Oversold ≠ buy", "Divergences are more useful than absolute levels", "Always use RSI with trend context"], quiz: [{ question: "RSI above 70 means...", options: ["Sell immediately", "Strong momentum — not automatic sell", "Buy more", "Close platform"], correctAnswer: 1, explanation: "RSI 70+ shows strong momentum. In uptrends, this is normal.", tags: ["Technical"] }, { question: "What is bearish RSI divergence?", options: ["RSI below 30", "Price new high but RSI lower high", "RSI crosses 50", "Both falling"], correctAnswer: 1, explanation: "Price reaches new high but RSI doesn't match = weakening momentum.", tags: ["Technical"] }, { question: "Best way to use RSI?", options: ["Only signal", "Confirmation alongside trend analysis", "Only daily charts", "Ignore it"], correctAnswer: 1, explanation: "RSI works best combined with other analysis.", tags: ["Technical"] }], related_lessons: ["understanding-macd", "support-resistance"] },
  { id: "understanding-macd", slug: "understanding-macd", title: "Understanding MACD", icon: "📶", category: "Technical", difficulty: "Medium", duration_minutes: 7, xp_reward: 30, summary: "Learn how MACD tracks momentum shifts via crossovers, histogram, and divergences.", why_it_matters: "MACD identifies trend changes early, showing when momentum direction is shifting.", content: [{ heading: "How MACD works", body: ["MACD = 26-period EMA minus 12-period EMA. Above zero = bullish, below = bearish.", "Signal line (9-period EMA of MACD) creates crossover signals."] }, { heading: "Reading signals", body: ["Bullish crossover: MACD crosses above signal line. Bearish = opposite.", "Histogram shows gap between MACD and signal. Shrinking = crossover approaching."] }, { heading: "Divergences", body: ["Price new low but MACD higher low = selling fading. Potential reversal.", "Higher timeframe divergences are more reliable."] }, { heading: "When this fails", body: ["MACD is lagging. In choppy sideways markets, it whipsaws with false crossovers."] }], common_mistake: "Trading every crossover without considering the broader trend.", practical_example: "Bitcoin's daily MACD crossed bullish in Jan 2023 near $16k and stayed bullish as price rallied to $25k.", takeaways: ["MACD measures relationship between two MAs", "Crossovers signal momentum shifts", "Histogram shows momentum strength", "Best in trending markets; avoid in chop"], quiz: [{ question: "What is a bullish MACD crossover?", options: ["Price at ATH", "MACD crosses above signal line", "Volume increased", "Stock split"], correctAnswer: 1, explanation: "MACD crossing above the signal line indicates positive momentum.", tags: ["Technical"] }, { question: "Where does MACD perform worst?", options: ["Strong uptrends", "Strong downtrends", "Choppy sideways markets", "High volume"], correctAnswer: 2, explanation: "Moving averages create false crossovers in ranging markets.", tags: ["Technical"] }, { question: "Shrinking histogram means?", options: ["Accelerating momentum", "Crossover approaching", "Market closed", "Volume dropping"], correctAnswer: 1, explanation: "Shrinking gap between lines = convergence = crossover likely.", tags: ["Technical"] }], related_lessons: ["understanding-rsi", "trend-market-structure"] },
  { id: "trend-market-structure", slug: "trend-market-structure", title: "Trend & Market Structure", icon: "🏗️", category: "Technical", difficulty: "Medium", duration_minutes: 8, xp_reward: 30, summary: "How trends form, how to read structure, and how to spot trend endings.", why_it_matters: "Market structure makes all other technical analysis work. Without it, every indicator is unreliable.", content: [{ heading: "Trend basics", body: ["Uptrend = higher highs (HH) + higher lows (HL). Downtrend = lower highs (LH) + lower lows (LL)."] }, { heading: "Break of structure", body: ["BOS: when the HH/HL or LH/LL pattern breaks. In an uptrend, price breaking the last HL = structure shift.", "One of the most important signals in trading."] }, { heading: "Ranging markets", body: ["Price bouncing between S&R without trending. Recognise this to avoid forcing trend strategies.", "Ranges eventually break, starting the next trend."] }, { heading: "Multi-timeframe", body: ["Your 5-min can be bearish while daily is bullish. Higher timeframe usually wins."] }], common_mistake: "Trying to call exact tops and bottoms. Structure breaks tell you after the fact — trying to predict is gambling.", practical_example: "A stock makes HH/HL for two months. Then it makes a lower high and breaks the last HL. Uptrend may be done.", takeaways: ["Uptrend = HH + HL; Downtrend = LH + LL", "BOS signals potential trend change", "Ranges need different strategies", "Higher timeframes override lower ones"], quiz: [{ question: "What defines an uptrend?", options: ["Fast price rise", "Higher highs and higher lows", "RSI above 50", "Positive news"], correctAnswer: 1, explanation: "Structurally: each peak higher, each pullback higher.", tags: ["Technical"] }, { question: "What is break of structure?", options: ["Market close", "HH/HL or LH/LL pattern violated", "Stock split", "Volume at zero"], correctAnswer: 1, explanation: "When price violates the established structural pattern.", tags: ["Technical"] }, { question: "Daily vs 5-min trend conflict?", options: ["5-min wins", "Daily wins", "Cancel out", "More volume wins"], correctAnswer: 1, explanation: "Higher timeframes represent larger flows and longer-term sentiment.", tags: ["Technical"] }], related_lessons: ["support-resistance", "bull-bear-markets"] },
  { id: "risk-management", slug: "risk-management", title: "Risk Management", icon: "🛡️", category: "Risk", difficulty: "Medium", duration_minutes: 8, xp_reward: 35, summary: "The most important trading skill: protecting your capital.", why_it_matters: "70% win rate still blows accounts if losses are too large. Risk management is everything.", content: [{ heading: "Core principle", body: ["Never risk more than 1-2% per trade.", "With $10,000 at 2%: max $200 loss per trade. 10 losses in a row = still $8,000."] }, { heading: "Risk-reward ratio", body: ["Define risk (stop) and reward (target) before entering. 1:2 = risk $100 to make $200.", "At 1:2, you only need 40% win rate to profit."] }, { heading: "Stop losses", body: ["Every trade must have a stop loss. No exceptions.", "Mental stops fail — your brain rationalises holding. Use hard stops."] }, { heading: "When this fails", body: ["Flash crashes and gaps can skip stops (slippage). Never risk catastrophic amounts."] }], common_mistake: "No stop loss, hoping a loser comes back. Small losses become account-ending disasters.", practical_example: "Buy $100, stop $97 (risk $3), target $106 (gain $6). 1:2 R:R. Win 5/10 = net +$15.", takeaways: ["Never risk more than 1-2% per trade", "R:R matters more than win rate", "Always use hard stops", "Surviving > winning any single trade"], quiz: [{ question: "$10k account, 2% rule — max risk per trade?", options: ["$1,000", "$500", "$200", "$50"], correctAnswer: 2, explanation: "2% of $10,000 = $200.", tags: ["Risk"] }, { question: "At 1:2 R:R, min win rate to profit?", options: ["50%+", "70%+", "33%+", "90%+"], correctAnswer: 2, explanation: "At 34%: 34 wins × $2 = $68, 66 losses × $1 = $66. Net positive.", tags: ["Risk"] }, { question: "Why are mental stops unreliable?", options: ["Brokers block them", "Your brain rationalises holding", "Illegal", "Only work in bull markets"], correctAnswer: 1, explanation: "Cognitive biases make you find reasons to hold losers.", tags: ["Risk"] }, { question: "What is slippage?", options: ["Extra fees", "Stop executes at worse price due to gaps", "RSI below 20", "Wrong order"], correctAnswer: 1, explanation: "Fast moves can cause stops to fill at worse prices.", tags: ["Risk"] }], related_lessons: ["position-sizing", "fomo-and-chasing"] },
  { id: "position-sizing", slug: "position-sizing", title: "Position Sizing", icon: "⚖️", category: "Risk", difficulty: "Medium", duration_minutes: 6, xp_reward: 30, summary: "Calculate exactly how many shares to buy based on risk and stop loss.", why_it_matters: "Position sizing translates risk rules into action. Without it, your 1% rule is meaningless.", content: [{ heading: "The formula", body: ["Position size = Risk amount ÷ Stop loss distance per share.", "With $10k, 1% risk ($100), $2 stop = 50 shares. Dollar risk stays constant."] }, { heading: "Consistent sizing", body: ["Random sizing makes results unpredictable. Consistency makes your edge work over time."] }, { heading: "Adjusting for volatility", body: ["High volatility = wider stops = smaller positions. Low volatility = tighter stops = more shares.", "Professionals adapt. They don't buy 100 shares of everything."] }], common_mistake: "Fixed 100 shares regardless of volatility. Some trades become 5x riskier without you knowing.", practical_example: "Trade A: $50 entry, $48 stop, $100 risk → 50 shares. Trade B: $200 entry, $190 stop, $100 risk → 10 shares. Same risk.", takeaways: ["Size = Risk ÷ Stop distance", "Keep dollar risk consistent", "Wider stops = smaller positions", "Never use fixed share counts"], quiz: [{ question: "$20k, 1% risk, $5 stop. How many shares?", options: ["100", "40", "200", "20"], correctAnswer: 1, explanation: "1% of $20k = $200. $200 ÷ $5 = 40 shares.", tags: ["Risk"] }, { question: "Why is fixed 100 shares bad?", options: ["Too many", "Makes some trades much riskier", "Brokers block it", "Penny stocks only"], correctAnswer: 1, explanation: "100 shares of $10 with $1 stop = $100 risk. 100 of $300 with $15 stop = $1,500. 15x difference.", tags: ["Risk"] }, { question: "How to size a volatile stock?", options: ["More shares for bigger moves", "Wider stop, fewer shares", "Same amount", "Don't trade it"], correctAnswer: 1, explanation: "Wider stops keep you in trade but mean fewer shares to maintain constant dollar risk.", tags: ["Risk"] }], related_lessons: ["risk-management", "fomo-and-chasing"] },
  { id: "fomo-and-chasing", slug: "fomo-and-chasing", title: "FOMO and Chasing", icon: "😰", category: "Psychology", difficulty: "Medium", duration_minutes: 6, xp_reward: 30, summary: "Why FOMO destroys accounts and how to stop chasing trades.", why_it_matters: "FOMO causes late entries, oversizing, and plan abandonment. It blows more accounts than bad analysis.", content: [{ heading: "What FOMO looks like", body: ["Seeing a stock up 30% and jumping in without a plan.", "Copying social media trades without realising they entered hours earlier."] }, { heading: "Why it's dangerous", body: ["You enter near the top when smart money is selling. R:R becomes terrible.", "FOMO causes oversizing — urgency overrides rules."] }, { heading: "How to manage it", body: ["Accept that you will miss trades. There's always another opportunity.", "Use a pre-trade checklist. If criteria aren't met, walk away.", "Wait for pullbacks instead of chasing the initial surge."] }], common_mistake: "Convincing yourself a late entry is 'fine' because the trend is strong. By the time FOMO hits, you're buying the last leg.", practical_example: "Stock gaps +20%. You chase at +25%. It hits +30%, reverses to +5%. You panic sell at a loss. Patient traders waited for the +10% pullback.", takeaways: ["FOMO = late entries at worst prices", "There is always another trade", "Pre-trade checklist filters emotion", "Wait for pullbacks, not parabolic moves"], quiz: [{ question: "Main risk of FOMO entries?", options: ["Broker rejection", "Bad price, terrible R:R", "Trading halt", "Always lose"], correctAnswer: 1, explanation: "FOMO pushes you near the top where R:R is poor.", tags: ["Psychology"] }, { question: "Best defence against FOMO?", options: ["No social media", "Pre-trade checklist and rules", "One stock only", "Tiny positions"], correctAnswer: 1, explanation: "Checklists force objective evaluation.", tags: ["Psychology"] }, { question: "Missed a big move — what to do?", options: ["Chase immediately", "Wait for a pullback", "Short it", "Switch stocks"], correctAnswer: 1, explanation: "Pullbacks after big moves often offer better entries.", tags: ["Psychology"] }], related_lessons: ["risk-management", "breakouts-vs-fakeouts"] },
  { id: "breakouts-vs-fakeouts", slug: "breakouts-vs-fakeouts", title: "Breakouts vs Fake Breakouts", icon: "💥", category: "Strategy", difficulty: "Hard", duration_minutes: 9, xp_reward: 40, summary: "Distinguish real breakouts from traps and trade both profitably.", why_it_matters: "Breakout trading is popular but 60-70% of breakouts fail. Knowing how to confirm or avoid them is a serious edge.", content: [{ heading: "What is a breakout?", body: ["Price moves beyond a defined level with conviction — higher volume, wider candles, follow-through."] }, { heading: "What is a fakeout?", body: ["Price briefly passes a level then reverses, trapping traders.", "Institutions push through levels to trigger stops before reversing."] }, { heading: "Confirming real breakouts", body: ["Volume: real breakouts have significantly higher volume.", "Candle close: wait for the candle to close beyond the level.", "Retest: best entries come when price breaks out, pulls back to the level, and bounces."] }, { heading: "Trading fakeouts", body: ["Trapped traders provide fuel for the reversal. Identify fakeouts early and trade the reverse with a tight stop."] }], common_mistake: "Entering every breakout without confirmation. This leads to repeated fakeout traps.", practical_example: "Stock consolidates below $50 for two weeks. Breaks above on heavy volume, closes $51. Retests $50 next day, holds, rallies to $58. Patient trader enters at $50.50 on retest.", takeaways: ["Real breakouts need volume + candle close", "60-70% of breakouts fail", "Retests offer best R:R entries", "Fakeouts create opportunities for patient traders"], quiz: [{ question: "What confirms a real breakout?", options: ["Wick above resistance", "Volume + candle close beyond level", "News headline", "RSI above 50"], correctAnswer: 1, explanation: "Close beyond the level with higher volume = genuine breakout.", tags: ["Strategy", "Technical"] }, { question: "What is a retest?", options: ["Same trade twice", "Price breaks out, pulls back to level, bounces", "Stop hit + re-entry", "Retaking ATH"], correctAnswer: 1, explanation: "Retests confirm the broken level now acts as support.", tags: ["Strategy"] }, { question: "Why are fakeouts opportunities?", options: ["Always lead to bigger breakouts", "Trapped traders fuel the reversal", "Easier to spot", "Broker rebates"], correctAnswer: 1, explanation: "Trapped traders' forced exits add momentum to the reversal.", tags: ["Strategy"] }, { question: "Breakout failure rate?", options: ["10-20%", "30-40%", "60-70%", "90-95%"], correctAnswer: 2, explanation: "Studies suggest 60-70% failure, making confirmation essential.", tags: ["Strategy"] }], related_lessons: ["support-resistance", "fomo-and-chasing"] },
  // === NEW INTERMEDIATE / ADVANCED LESSONS ===
  { id: "volume-analysis", slug: "volume-analysis", title: "Volume Analysis", icon: "📢", category: "Technical", difficulty: "Medium", duration_minutes: 8, xp_reward: 30, summary: "Understand what volume tells you about conviction behind price moves.", why_it_matters: "Price shows direction. Volume shows conviction. A move without volume is a suggestion — a move with volume is a statement.", content: [{ heading: "What volume measures", body: ["Volume counts the number of shares or contracts traded in a given period.", "High volume = strong participation. Low volume = weak conviction."] }, { heading: "Volume confirms moves", body: ["Breakouts on high volume are more likely to follow through.", "Rallies on declining volume suggest exhaustion — fewer participants are driving price higher."] }, { heading: "Volume spikes", body: ["Sudden volume spikes often mark capitulation (panic selling) or climax tops (euphoric buying).", "These can signal reversals or the end of a trend leg."] }, { heading: "When volume misleads", body: ["Options expiry and index rebalancing can inflate volume without meaningful directional conviction.", "Context matters — not all high volume is smart money."] }], common_mistake: "Ignoring volume entirely and relying only on price patterns. A breakout without volume is a setup for a fakeout.", practical_example: "A stock breaks above $100 on 3x average volume. The next day, volume stays elevated and price holds above $100. That's conviction. Compare to a breakout on half average volume that reverses the next day.", takeaways: ["Volume = conviction behind price", "Breakouts need volume confirmation", "Declining volume on rallies = exhaustion risk", "Volume spikes can signal reversals"], quiz: [{ question: "What does high volume during a breakout suggest?", options: ["Price will reverse", "Strong conviction behind the move", "Market is closed", "No significance"], correctAnswer: 1, explanation: "High volume means many participants agree on the direction.", tags: ["Technical"] }, { question: "Declining volume during a rally suggests...", options: ["Strength building", "Potential exhaustion", "Guaranteed reversal", "Higher highs coming"], correctAnswer: 1, explanation: "Fewer buyers pushing price up = the rally may be running out of fuel.", tags: ["Technical"] }, { question: "What can cause misleading volume spikes?", options: ["Options expiry and rebalancing", "Strong earnings", "Retail trading only", "Market holidays"], correctAnswer: 0, explanation: "Index rebalancing and options expiry create mechanical volume, not directional conviction.", tags: ["Technical"] }], related_lessons: ["breakouts-vs-fakeouts", "support-resistance"] },
  { id: "candlestick-patterns", slug: "candlestick-patterns", title: "Candlestick Patterns", icon: "🕯️", category: "Technical", difficulty: "Medium", duration_minutes: 9, xp_reward: 35, summary: "Read individual and multi-candle patterns for clues about buyer and seller control.", why_it_matters: "Candlesticks show the battle between buyers and sellers within each period. Reading them gives you a speed advantage over indicator-only traders.", content: [{ heading: "Candle anatomy", body: ["Body = open to close. Wick = high and low extremes.", "Long body = strong conviction. Long wick = rejection from a level."] }, { heading: "Key single candles", body: ["Hammer/Pin bar: long lower wick, small body at top. Rejection of lower prices — bullish at support.", "Shooting star: long upper wick, small body at bottom. Rejection of higher prices — bearish at resistance.", "Doji: open ≈ close. Indecision. Meaningful at key levels."] }, { heading: "Multi-candle patterns", body: ["Engulfing: current candle body completely covers prior candle. Shows momentum shift.", "Morning star / Evening star: three-candle reversal patterns at extremes."] }, { heading: "When patterns fail", body: ["Candle patterns without context are noise. A hammer in the middle of a range means less than a hammer at major support.", "Always combine with S&R, trend, and volume."] }], common_mistake: "Trading every single hammer or engulfing candle without considering where it forms. Location matters more than the pattern itself.", practical_example: "A bullish engulfing candle forms right at the $50 support zone after a clean pullback. Volume spikes. This is a high-probability reversal signal. The same candle in the middle of a range? Just noise.", takeaways: ["Body = conviction, wick = rejection", "Location of the pattern matters most", "Combine with S&R and volume", "Patterns are clues, not guarantees"], quiz: [{ question: "What does a long lower wick on a candle suggest?", options: ["Sellers are in control", "Buyers rejected lower prices", "No one is trading", "Price will gap down"], correctAnswer: 1, explanation: "A long lower wick means price pushed down but buyers pushed it back up — rejection of lower levels.", tags: ["Technical"] }, { question: "When is a hammer most meaningful?", options: ["In the middle of a range", "At a major support zone", "On a Monday", "After a gap up"], correctAnswer: 1, explanation: "A hammer at support shows buyers defending a key level. In the middle of a range, it's less significant.", tags: ["Technical"] }, { question: "What does a bearish engulfing candle show?", options: ["Buyers are winning", "Sellers overwhelmed buyers", "Volume is low", "Trend continuation"], correctAnswer: 1, explanation: "The bearish candle completely covers the prior bullish candle — sellers took control.", tags: ["Technical"] }], related_lessons: ["support-resistance", "trend-market-structure"] },
  { id: "moving-averages", slug: "moving-averages", title: "Moving Averages", icon: "〰️", category: "Technical", difficulty: "Medium", duration_minutes: 7, xp_reward: 30, summary: "Use moving averages to identify trends, dynamic S&R, and momentum shifts.", why_it_matters: "Moving averages smooth noise and reveal the underlying trend. They're the backbone of most systematic trading strategies.", content: [{ heading: "SMA vs EMA", body: ["SMA (Simple): equal weight to all periods. Smoother but slower to react.", "EMA (Exponential): heavier weight on recent prices. More responsive."] }, { heading: "Common settings", body: ["20 EMA: short-term trend and dynamic support in uptrends.", "50 SMA: medium-term trend. Institutional favourite.", "200 SMA: long-term trend. Price above = bullish bias. Below = bearish."] }, { heading: "Crossovers", body: ["Golden cross: 50 MA crosses above 200 MA. Bullish long-term signal.", "Death cross: 50 MA crosses below 200 MA. Bearish signal.", "These are lagging — by the time they trigger, a significant move has already happened."] }, { heading: "Dynamic support and resistance", body: ["In strong trends, price often bounces off the 20 or 50 MA.", "Use MAs as zones for pullback entries, not as exact bounce levels."] }], common_mistake: "Using MA crossovers as standalone entry signals. They lag significantly and whipsaw in choppy markets.", practical_example: "AAPL pulls back to its rising 50-day SMA for the third time in an uptrend. Each time it bounced. You buy near the 50 MA with a stop just below. This is a high-probability pullback setup.", takeaways: ["MAs reveal trend direction", "20/50/200 are the key levels", "Crossovers lag — use for context, not timing", "Price bouncing off MAs = dynamic S&R"], quiz: [{ question: "What does price above the 200 MA generally suggest?", options: ["Bearish trend", "Bullish bias", "Sideways market", "Overbought"], correctAnswer: 1, explanation: "Price above the 200 MA = long-term uptrend. Institutions watch this level closely.", tags: ["Technical"] }, { question: "Why are MA crossovers problematic?", options: ["They're too fast", "They lag and whipsaw in ranges", "They only work on crypto", "They require premium data"], correctAnswer: 1, explanation: "MAs are lagging indicators. In choppy markets, crossovers generate false signals.", tags: ["Technical"] }, { question: "The 20 EMA in a strong uptrend often acts as...", options: ["Resistance", "Dynamic support", "A sell signal", "Nothing useful"], correctAnswer: 1, explanation: "In uptrends, price regularly pulls back to the 20 EMA and bounces — making it dynamic support.", tags: ["Technical"] }], related_lessons: ["trend-market-structure", "understanding-macd"] },
  { id: "correlation-trading", slug: "correlation-trading", title: "Correlation Trading", icon: "🔗", category: "Advanced", difficulty: "Hard", duration_minutes: 8, xp_reward: 40, summary: "Understand how assets move together and how to use correlations for confirmation and risk management.", why_it_matters: "If you're long on two highly correlated assets, you're not diversified — you're doubling down. Understanding correlation prevents hidden concentration risk.", content: [{ heading: "What is correlation?", body: ["+1 = move together. -1 = move opposite. 0 = no relationship.", "Stocks in the same sector (AAPL/MSFT) tend to be positively correlated."] }, { heading: "Using correlation", body: ["Confirmation: if tech stocks rally but your tech pick doesn't, something's wrong.", "Risk management: avoid holding 5 positions that all correlate heavily to the same factor.", "Hedging: negatively correlated assets can offset risk."] }, { heading: "Correlation breaks down", body: ["Correlations shift in crises. 'Everything sells' events break historical patterns.", "Don't assume correlations are permanent — they change with macro regimes."] }], common_mistake: "Thinking you're diversified because you hold 5 different stocks that all move with the S&P 500. That's concentration, not diversification.", practical_example: "You're long AAPL, MSFT, and GOOG. All three drop 4% together because they correlate at 0.85+. Your 'diversified' portfolio just had a correlated drawdown. One S&P 500 short would have offset all three.", takeaways: ["Correlation measures how assets move together", "High correlation = hidden concentration risk", "Use correlation for confirmation signals", "Correlations break in extreme events"], quiz: [{ question: "If two assets have a correlation of +0.9, what does that mean?", options: ["They move opposite", "They move almost identically", "No relationship", "One causes the other"], correctAnswer: 1, explanation: "0.9 correlation means they move in the same direction ~90% of the time.", tags: ["Advanced", "Risk"] }, { question: "Why is holding 5 correlated stocks risky?", options: ["Too many positions", "They'll all drop together", "Brokers charge more", "Dividends cancel out"], correctAnswer: 1, explanation: "If they're all correlated, one bad move hits your entire portfolio simultaneously.", tags: ["Risk", "Advanced"] }, { question: "When do correlations break down most?", options: ["Bull markets", "During crises and extreme events", "Weekends", "Low volume"], correctAnswer: 1, explanation: "In panic selling, correlations spike as 'everything sells' regardless of fundamentals.", tags: ["Advanced"] }], related_lessons: ["risk-management", "position-sizing"] },
  { id: "trade-journaling", slug: "trade-journaling", title: "Trade Journaling", icon: "📝", category: "Strategy", difficulty: "Easy", duration_minutes: 6, xp_reward: 25, summary: "Build a trade journal that actually improves your performance over time.", why_it_matters: "You can't improve what you don't measure. A good journal exposes patterns in your behaviour that you can't see in real time.", content: [{ heading: "Why journal?", body: ["Journaling turns trading from gut feel into data-driven improvement.", "After 50 trades, patterns emerge: your best setups, worst times, emotional triggers."] }, { heading: "What to record", body: ["Entry/exit price, position size, stop loss, target, R:R ratio.", "Your thesis — why you entered. One sentence.", "Your emotion — how you felt before and during the trade.", "Outcome and what you learned."] }, { heading: "How to review", body: ["Weekly: scan for repeated mistakes.", "Monthly: identify your best setup type, best session, worst bias.", "Look for edge — which setups actually make you money over 20+ trades?"] }, { heading: "Common excuses", body: ["'I'll remember' — no you won't. Write it down.", "'It takes too long' — 2 minutes per trade. Your account balance is worth 2 minutes."] }], common_mistake: "Only journaling winning trades. You learn far more from losses and mistakes than from wins.", practical_example: "After 30 journal entries, you notice that trades taken before 10 AM EST have a 35% win rate vs 58% after 10 AM. You stop trading the first 30 minutes. Win rate improves immediately.", takeaways: ["Journal every trade — especially losses", "Record thesis, emotion, and outcome", "Review weekly and monthly for patterns", "Data beats memory every time"], quiz: [{ question: "Why journal losing trades?", options: ["To feel bad", "Losses reveal patterns you can fix", "Brokers require it", "To avoid taxes"], correctAnswer: 1, explanation: "Losses contain the most useful data. Patterns in your losses show exactly what to fix.", tags: ["Strategy"] }, { question: "What's the most underrated thing to record?", options: ["Ticker symbol", "Your emotional state", "The date", "Chart colour scheme"], correctAnswer: 1, explanation: "Emotional state reveals when you're trading on tilt, fear, or overconfidence.", tags: ["Psychology", "Strategy"] }, { question: "How often should you review your journal?", options: ["Never — just write", "Weekly and monthly", "Only after big losses", "Once a year"], correctAnswer: 1, explanation: "Weekly catches quick patterns. Monthly reveals deeper behavioural trends.", tags: ["Strategy"] }], related_lessons: ["fomo-and-chasing", "risk-management"] },
  { id: "building-trading-plan", slug: "building-trading-plan", title: "Building a Trading Plan", icon: "🗺️", category: "Strategy", difficulty: "Hard", duration_minutes: 10, xp_reward: 45, summary: "Create a structured trading plan that removes emotion and gives every trade a framework.", why_it_matters: "A trading plan is the difference between a trader and a gambler. Without one, every decision is emotional. With one, every decision has structure.", content: [{ heading: "What a plan includes", body: ["Market focus: which markets and timeframes you trade.", "Setup criteria: exact conditions needed to enter a trade.", "Risk rules: max risk per trade, max daily loss, max open positions.", "Entry and exit rules: how you get in, how you get out, where your stop goes."] }, { heading: "Why plans fail", body: ["Too vague: 'buy when it looks good' is not a plan.", "Too rigid: markets change. Your plan needs room to breathe.", "Not followed: a perfect plan you ignore is worse than no plan."] }, { heading: "Building yours", body: ["Start simple. One market, one setup type, one timeframe.", "Backtest it on 20+ historical examples before going live.", "Track results in your journal. Iterate based on data, not feelings."] }, { heading: "Adapting over time", body: ["Your plan should evolve as you learn — but changes should be data-driven, not emotional.", "If you change your plan after one bad trade, that's not adaptation — that's panic."] }], common_mistake: "Building a plan that's so complex you can't follow it under pressure. The best plans are simple enough to execute when your emotions are screaming.", practical_example: "Plan: trade pullbacks to the 20 EMA in stocks above the 200 SMA. Entry: bounce candle at 20 EMA. Stop: below prior swing low. Target: 2x risk. Max risk: 1%. That's a complete plan in 4 lines.", takeaways: ["A plan removes emotion from decisions", "Start simple: one market, one setup", "Backtest before going live", "Iterate based on data, not feelings"], quiz: [{ question: "What's the most important element of a trading plan?", options: ["The market you trade", "Clear entry and exit rules", "Your broker", "Account size"], correctAnswer: 1, explanation: "Without clear rules for when to enter and exit, you're guessing every time.", tags: ["Strategy"] }, { question: "Why should plans start simple?", options: ["Complex plans are illegal", "Simple plans are easier to follow under pressure", "You can only trade one stock", "Simple means faster profits"], correctAnswer: 1, explanation: "Under pressure, you'll default to the simplest version of your plan. Make that version good.", tags: ["Strategy"] }, { question: "When should you change your plan?", options: ["After one bad trade", "Based on 20+ trade data", "When someone on Twitter disagrees", "Every Monday"], correctAnswer: 1, explanation: "One trade is noise. 20+ trades is data. Change your plan based on patterns, not reactions.", tags: ["Strategy"] }], related_lessons: ["trade-journaling", "risk-management"] },
];

